/* Chax Training: small, dependency-free, offline first training companion. */
const $=s=>document.querySelector(s), app=$('#app'), overlay=$('#overlay');
const days=[
 {label:'Sat',title:'PUSH',ar:'الصدر والكتفان والترايسبس',key:'Day 1 · Push',rest:false,number:1},
 {label:'Sun',title:'PULL',ar:'الظهر والبايسبس',key:'Day 2 · Pull',rest:false,number:2},
 {label:'Mon',title:'LEGS',ar:'تمرين الساقين',key:'Day 3 · Legs',rest:false,number:3},
 {label:'Tue',title:'REST DAY',ar:'استشفاء',key:'rest-tue',rest:true},
 {label:'Wed',title:'UPPER + ARMS',ar:'الجزء العلوي والذراعان',key:'Day 4 · Upper + Arms',rest:false,number:4},
 {label:'Thu',title:'ARMS + DELTS',ar:'الذراعان والكتفان',key:'Day 5 · Arms + Delts',rest:false,number:5},
 {label:'Fri',title:'REST DAY',ar:'استشفاء',key:'rest-fri',rest:true}
];
const defaults={settings:{sound:true,vibrate:true,autoStart:true,theme:'dark',language:'en',equipment:[],schedule:['Sat','Sun','Mon','Wed','Thu']},history:[],bodyweight:[],swaps:{}};
function read(){try{const saved=JSON.parse(localStorage.getItem('iron-data')||'{}');return {...defaults,...saved,settings:{...defaults.settings,...saved.settings},history:Array.isArray(saved.history)?saved.history:[],bodyweight:Array.isArray(saved.bodyweight)?saved.bodyweight:[],swaps:saved.swaps||{}}}catch(e){return structuredClone(defaults)}}
let state=read(), workout=null, timer=null, wake=null, selectedDay=todayIndex(), currentPage='home', sessionClock=null;
if(!['en','ar'].includes(state.settings.language))state.settings.language='en';
(function applySavedSchedule(){const labels=state.settings.schedule||['Sat','Sun','Mon','Wed','Thu'];const open=['Sat','Sun','Mon','Tue','Wed','Thu'];const sessionKeys=['Day 1 · Push','Day 2 · Pull','Day 3 · Legs','Day 4 · Upper + Arms','Day 5 · Arms + Delts'];const byKey=new Map(days.map(d=>[d.key,d]));const moved=labels.map((day,i)=>({...byKey.get(sessionKeys[i]),label:open.includes(day)?day:['Sat','Sun','Mon','Wed','Thu'][i]}));const daySlots=open.map((label)=>moved.find(d=>d.label===label)||{label,title:'REST DAY',ar:'استشفاء',key:`rest-${label.toLowerCase()}`,rest:true});daySlots.push(byKey.get('rest-fri'));days.splice(0,days.length,...daySlots)})();
function save(){try{localStorage.setItem('iron-data',JSON.stringify(state))}catch(e){toast('Could not save data on this device')}}
function todayIndex(){return (new Date().getDay()+1)%7}
function isArabic(){return state.settings.language==='ar'}
function dayTitle(d){return isArabic()?d.ar:d.title}
function dayLabel(d){return isArabic()?({'Mon':'الإثنين','Tue':'الثلاثاء','Wed':'الأربعاء','Thu':'الخميس','Fri':'الجمعة','Sat':'السبت','Sun':'الأحد'}[d.label]||d.label):d.label}
function exerciseName(e){return isArabic()?(AR_EXERCISES[e.id]?.name||e.name):e.name}
function exerciseCue(e){return isArabic()?(AR_EXERCISES[e.id]?.cue||e.cue):e.cue}
function muscleNames(list){return (list||[]).map(x=>isArabic()?({'chest':'العضلات الصدرية','shoulders':'العضلة الدالية','triceps':'العضلة ثلاثية الرؤوس العضدية','lats':'العضلة الظهرية العريضة','middle back':'العضلات المعينية وشبه المنحرفة','biceps':'العضلة ذات الرأسين العضدية','quadriceps':'العضلة رباعية الرؤوس الفخذية','hamstrings':'عضلات الفخذ الخلفية','calves':'العضلة ثلاثية الرؤوس الربلية','glutes':'العضلات الألوية','abdominals':'العضلات البطنية','traps':'العضلة شبه المنحرفة'}[x]||x):titleCase(x)).join(isArabic()?' · ':' · ')}
const AR_EXERCISES={
 'dumbbell-bench-press':{name:'بنش برس مستوٍ بالدمبلز (Dumbbell Bench Press)',cue:'ثبّت القدمين، واسحب لوحي الكتف إلى الخلف والأسفل، وأنزل الدمبلين بتحكم.'},
 'incline-dumbbell-press':{name:'بنش برس مائل لأعلى بالدمبلز (Incline Dumbbell Press)',cue:'اضبط المقعد على ميل يقارب ٣٠ درجة، واجعل المرفقين بزاوية نحو ٤٥° عن الجذع، وأنزل إلى أعلى الصدر.'},
 'seated-dumbbell-shoulder-press':{name:'ضغط كتف جالس بالدمبلز (Seated Dumbbell Shoulder Press)',cue:'أسند الظهر، وحافظ على الأضلاع إلى الأسفل، وتجنب تقويس أسفل الظهر.'},
 'cable-lateral-raise':{name:'رفرفة جانبية بالكابل (Cable Lateral Raise)',cue:'ابدأ الحركة بالمرفق وارفع الذراع إلى مستوى الكتف بتحكم.'},
 'rope-triceps-pushdown':{name:'ترايسبس بوش داون بالحبل (Rope Triceps Pushdown)',cue:'ثبّت المرفقين بجانب الجذع وافصل طرفي الحبل في نهاية الحركة.'},
 'lat-pulldown':{name:'سحب لاتس بقبضة علوية (Lat Pulldown)',cue:'استخدم قبضة علوية بعرض الكتفين واسحب القضيب إلى أعلى الصدر.'},
 'chest-supported-dumbbell-row':{name:'تجديف بالدمبلز مع إسناد الصدر (Chest-Supported Dumbbell Row)',cue:'أبقِ الصدر ملاصقاً لمسند المقعد، واسحب المرفقين للخلف واعصر لوحي الكتف.'},
 'straight-arm-cable-pulldown':{name:'سحب مستقيم الذراعين بالكابل (Straight-Arm Cable Pulldown)',cue:'حافظ على انثناء طفيف في المرفقين واسحب المقبض بقوس نحو الفخذين.'},
 'reverse-pec-deck':{name:'رفرفة خلفية للكتف على الجهاز (Reverse Pec Deck)',cue:'استخدم حملاً خفيفاً وابدأ الحركة بقيادة المرفقين.'},
 'hammer-curl':{name:'هامر كيرل (Hammer Curl)',cue:'حافظ على قبضة محايدة وثبات المرفقين بجانب الجسم.'},
 'leg-press-quad-stance':{name:'ليج برس · تركيز كواد (Leg Press, Quad Stance)',cue:'انزل بمدى حركي كامل ومريح وادفع عبر منتصف القدم مع إبقاء أسفل الظهر على المسند.'},
 'walking-lunge-dumbbells':{name:'لونجز مشي بالدمبل (Walking Dumbbell Lunges)',cue:'اتخذ خطوة طويلة، وحافظ على الجذع منتصباً وتحكم في النزول.'},
 'leg-extension':{name:'ليج إكستنشن (Leg Extension)',cue:'اثبت ثانية واحدة عند بسط الركبة، ثم اخفض الوزن بتحكم.'},
 'lying-leg-curl':{name:'ليج كيرل مستلقياً (Lying Leg Curl)',cue:'أبقِ الوركين ملامسين للوسادة وتحكم في مرحلة خفض الوزن.'},
 'standing-calf-raise':{name:'رفع السمانة واقفاً على الجهاز (Standing Calf Raise)',cue:'انزل إلى إطالة مريحة لعضلات الربلة، ثم توقف لحظة في الأعلى.'},
 'cable-fly':{name:'تفتيح صدر بالكابل (Cable Fly)',cue:'حافظ على انثناء خفيف في المرفقين وقرّب الذراعين مع عصر عضلات الصدر.'},
 'incline-fly-machine':{name:'تفتيح صدر مائل على الجهاز (Incline Fly Machine)',cue:'حافظ على انثناء خفيف في المرفقين واعصر عضلات الصدر دون رفع الكتفين.'},
 'seated-cable-row':{name:'تجديف بالكابل جالساً (Seated Cable Row)',cue:'اسحب المقبض نحو أسفل الأضلاع مع إبقاء العمود الفقري محايداً.'},
 'assisted-neutral-grip-pull-up':{name:'عقلة مساعدة بقبضة محايدة (Assisted Neutral-Grip Pull-Up)',cue:'ابدأ من تعليق مضبوط، واسحب حتى يتجاوز الذقن مستوى اليدين دون تأرجح.'},
 'dumbbell-lateral-raise':{name:'رفرفة جانبية بالدمبل (Dumbbell Lateral Raise)',cue:'أبقِ انثناءً طفيفاً في المرفقين وارفع الدمبلين إلى مستوى الكتفين.'},
 'cable-curl':{name:'بايسبس كيرل بالكابل (Cable Curl)',cue:'ثبّت المرفقين بمحاذاة الجذع وتجنب دفع الوركين أو التأرجح.'},
 'overhead-cable-triceps-extension':{name:'تمديد ترايسبس فوق الرأس بالكابل (Overhead Cable Triceps Extension)',cue:'وجّه المرفقين إلى الأمام، واسمح بامتداد مريح لعضلة الترايسبس.'},
 'romanian-deadlift-light-controlled':{name:'ديدليفت روماني · خفيف (Romanian Deadlift, RDL)',cue:'استخدم حملاً خفيفاً؛ ادفع الوركين للخلف مع ظهر محايد، وتوقف عند منتصف الساق.'},
 'leg-press-feet-high-and-wide':{name:'ليج برس · قدمان مرتفعتان ووقفة واسعة (High-and-Wide Leg Press)',cue:'أبقِ أسفل الظهر ملاصقاً للمسند، ولا تنزل إلى حد التفاف الحوض.'},
 'hip-thrust':{name:'هيب ثرست (Hip Thrust)',cue:'أبقِ الذقن منخفضاً، وادفع عبر الكعبين، واعصر الأليتين لحظة في الأعلى.'},
 'seated-leg-curl':{name:'ليج كيرل جالساً (Seated Leg Curl)',cue:'اضبط الوسادة فوق الكعبين مباشرة وتحكم في العودة.'},
 'seated-calf-raise':{name:'رفع السمانة جالساً على الجهاز (Seated Calf Raise)',cue:'انزل إلى إطالة عميقة ومريحة لعضلات الربلة، وتوقف لحظة في الأعلى.'},
 'cable-crunch':{name:'كرنش بالكابل (Cable Crunch)',cue:'قرّب الأضلاع من الحوض بثني العمود الفقري، مع تثبيت الوركين.'},
 'plank':{name:'بلانك (Plank)',cue:'حافظ على استقامة الرأس والجذع والحوض، مع شد عضلات البطن والأليتين.'}
};
const AR_STEPS={
 'dumbbell-bench-press':['استلقِ على المقعد وثبّت القدمين على الأرض؛ ابدأ والدمبلان بمحاذاة الصدر والرسغان فوق المرفقين.','ادفع الدمبلين عمودياً حتى قرب مدّ المرفقين، مع إبقاء لوحي الكتف مستقرين على المقعد.','اخفض الدمبلين ببطء إلى جانبي الصدر ثم كرر الحركة دون ارتداد.'],
 'incline-dumbbell-press':['اضبط مسند المقعد على ميل يقارب ٣٠° واستلقِ مع تثبيت القدمين والكتفين.','أنزل الدمبلين بمحاذاة أعلى الصدر مع توجيه المرفقين بزاوية تقارب ٤٥° عن الجذع.','ادفع إلى الأعلى بتحكم، مع الحفاظ على الرسغين فوق المرفقين.'],
 'seated-dumbbell-shoulder-press':['اجلس مع إسناد الظهر، وارفع الدمبلين إلى جانبي الكتفين والساعدين عموديين.','ادفع الدمبلين فوق الرأس دون تقويس أسفل الظهر أو رفع الأضلاع.','اخفضهما ببطء إلى مستوى الكتفين.'],
 'cable-lateral-raise':['قف بجانب بكرة منخفضة وامسك المقبض باليد البعيدة عن الجهاز.','ارفع الذراع جانبياً بقيادة المرفق حتى مستوى الكتف، مع ميل طفيف وثابت في المرفق.','اخفض المقبض ببطء إلى نقطة البداية دون تأرجح الجذع.'],
 'rope-triceps-pushdown':['قف أمام بكرة مرتفعة وامسك طرفي الحبل؛ قرّب المرفقين من جانبي الجذع.','مدّ المرفقين إلى الأسفل مع ثبات العضدين، وافصل طرفي الحبل عند نهاية الحركة.','أعد الساعدين إلى وضع البداية بتحكم مع إبقاء المرفقين ثابتين.'],
 'lat-pulldown':['اجلس وثبّت الفخذين تحت الوسادة، وامسك القضيب بقبضة علوية أوسع قليلاً من الكتفين.','اسحب لوحي الكتف إلى الأسفل ثم اجذب القضيب نحو أعلى الصدر مع ميل بسيط للجذع.','أعد القضيب إلى الأعلى ببطء حتى تمتد الذراعان دون فقدان التحكم.'],
 'chest-supported-dumbbell-row':['اضبط المقعد المائل واستلقِ عليه وصدرك مسنود؛ دع الدمبلين يتدليان أسفل الكتفين.','اسحب المرفقين إلى الخلف بمحاذاة الجذع حتى يصلا قرب مستوى الظهر، واعصر لوحي الكتف.','أنزل الدمبلين ببطء إلى وضع البداية دون رفع الصدر عن المسند.'],
 'straight-arm-cable-pulldown':['قف أمام بكرة مرتفعة وامسك المقبض بقبضة علوية؛ أمل الجذع قليلاً مع انثناء طفيف للمرفقين.','اسحب المقبض بقوس إلى الفخذين مع إبقاء زاوية المرفقين شبه ثابتة.','أعد الذراعين إلى الأعلى ببطء حتى تشعر بتمدد مريح في عضلات الظهر.'],
 'reverse-pec-deck':['اضبط المقعد بحيث تكون المقابض بمستوى الكتفين، وامسكها مع انثناء خفيف للمرفقين.','افتح الذراعين للخلف بقيادة المرفقين حتى اصطفافهما مع الجذع.','أعد المقابض ببطء إلى الأمام دون زيادة مدى الحركة عن المريح.'],
 'hammer-curl':['قف ممسكاً بالدمبلين بجانب الجسم مع توجيه راحتي اليدين نحو الداخل.','اثنِ المرفقين وارفع الدمبلين دون تحريك العضدين أو تأرجح الجذع.','اخفض الدمبلين ببطء مع الحفاظ على القبضة المحايدة.'],
 'leg-press-quad-stance':['اجلس على الجهاز وثبّت القدمين بعرض مناسب في منتصف المنصة؛ أبقِ الحوض وأسفل الظهر على المسند.','اخفض المنصة بثني الركبتين ضمن مدى مريح مع بقاء الركبتين بمحاذاة أصابع القدمين.','ادفع عبر منتصف القدم حتى قرب مدّ الركبتين، دون قفلهما أو رفع الحوض عن المسند.'],
 'walking-lunge-dumbbells':['قف معتدلاً ممسكاً بالدمبلين، وخذ خطوة طويلة إلى الأمام.','اخفض الجسم بثني الركبتين حتى تقترب الركبة الخلفية من الأرض مع بقاء الجذع منتصباً.','ادفع بقدمك الأمامية للعودة إلى الوقوف، ثم تقدم بالقدم الأخرى.'],
 'leg-extension':['اضبط محور الجهاز بمحاذاة مفصل الركبة واجعل الوسادة أمام أسفل الساق.','مدّ الركبتين حتى استقامة الساقين تقريباً وتوقف لحظة دون قفل المفصل.','اخفض الوزن ببطء حتى زاوية البداية.'],
 'lying-leg-curl':['استلقِ على البطن واضبط الوسادة فوق الكعبين بقليل؛ أبقِ الوركين ملاصقين للمقعد.','اثنِ الركبتين وارفع الوسادة نحو الأرداف دون رفع الحوض.','مدّ الركبتين ببطء حتى وضع البداية مع مقاومة الوزن.'],
 'standing-calf-raise':['ضع مقدمة القدمين على المنصة واضبط الوسادة على الكتفين؛ ابدأ والكعبان منخفضان بقدر مريح.','ارفع الكعبين إلى أعلى مدى مريح مع إبقاء الركبتين شبه ممدودتين.','اخفض الكعبين ببطء حتى تشعر بتمدد عضلات الربلة.'],
 'cable-fly':['قف بين بكرتين واضبطهما عند مستوى الصدر؛ أمسك المقبضين مع انثناء خفيف وثابت للمرفقين.','قرّب الذراعين أمام الصدر بقوس واسع دون تغيير زاوية المرفقين.','أعد الذراعين إلى الجانبين ببطء حتى امتداد مريح للصدر.'],
 'seated-cable-row':['اجلس مع ثني خفيف للركبتين وظهر محايد، وامسك المقبض والذراعان ممدودتان.','اسحب المرفقين للخلف نحو أسفل الأضلاع مع إبقاء الجذع ثابتاً.','مدّ الذراعين ببطء إلى الأمام دون تدوير الظهر.'],
 'assisted-neutral-grip-pull-up':['اضبط مقدار المساعدة وامسك المقابض المحايدة؛ ابدأ من تعليق مضبوط والذراعان ممدودتان.','اسحب لوحي الكتف إلى الأسفل ثم ارفع الجسم حتى يتجاوز الذقن مستوى اليدين.','انزل ببطء إلى التعليق مع الحفاظ على التحكم ودون تأرجح.'],
 'dumbbell-lateral-raise':['قف ممسكاً بالدمبلين أمام جانبي الفخذين، مع انثناء طفيف للمرفقين.','ارفع الذراعين جانبياً بقيادة المرفقين حتى مستوى الكتفين دون تأرجح.','اخفض الدمبلين ببطء إلى جانبي الجسم.'],
 'cable-curl':['قف أمام بكرة منخفضة وامسك المقبض؛ ثبّت المرفقين بمحاذاة الجذع.','اثنِ المرفقين وارفع المقبض نحو الكتفين دون تحريك العضدين.','اخفض المقبض ببطء حتى امتداد الذراعين بتحكم.'],
 'overhead-cable-triceps-extension':['قف وظهرك إلى بكرة منخفضة وامسك الحبل خلف الرأس؛ وجّه المرفقين إلى الأمام.','مدّ المرفقين إلى الأمام/الأعلى مع ثبات العضدين بجانب الرأس.','اثنِ المرفقين ببطء للعودة حتى تمدد مريح في العضلة ثلاثية الرؤوس.'],
 'romanian-deadlift-light-controlled':['ابدأ بوزن خفيف، والقدمان بعرض الوركين والركبتان مثنيتان قليلاً؛ حافظ على ظهر محايد.','ادفع الوركين للخلف وأنزل الوزن بمحاذاة الساقين حتى منتصف الساق أو قبل ذلك إذا تأثر وضع الظهر.','ادفع الوركين إلى الأمام للوقوف مع إبقاء الوزن خفيفاً؛ أوقف الحركة إذا صار الانزعاج حاداً.'],
 'leg-press-feet-high-and-wide':['ضع القدمين أعلى المنصة وبمسافة أوسع من الكتفين، مع توجيه الركبتين باتجاه أصابع القدمين.','اخفض المنصة ببطء ضمن مدى لا يرفع الحوض ولا يجعل أسفل الظهر يلتف عن المسند.','ادفع عبر القدمين للعودة دون قفل الركبتين.'],
 'hip-thrust':['اسند أعلى الظهر إلى المقعد وثبّت القدمين على الأرض؛ ضع الوزن فوق الوركين إن استُخدم.','ادفع عبر الكعبين وارفع الوركين حتى يصبح الجذع والفخذان بمحاذاة واحدة.','أبقِ الذقن منخفضاً واعصر الأليتين لحظة، ثم اخفض الوركين بتحكم.'],
 'seated-leg-curl':['اجلس واضبط محور الجهاز بمحاذاة الركبة والوسادة فوق الكعبين مباشرة.','اثنِ الركبتين واسحب الوسادة إلى الأسفل والخلف مع تثبيت الفخذين.','أعد الساقين ببطء إلى وضع البداية.'],
 'seated-calf-raise':['اجلس واضعاً مقدمة القدمين على المنصة والوسادة فوق أسفل الفخذين؛ ابدأ والكعبان منخفضان.','ارفع الكعبين إلى أعلى مدى مريح مع ثبات مقدمة القدمين.','اخفض الكعبين ببطء إلى تمدد مريح ثم كرر.'],
 'cable-crunch':['اركع أمام بكرة مرتفعة وامسك الحبل قرب الرأس؛ ثبّت الوركين والفخذين.','قرّب الأضلاع نحو الحوض بثني الجذع، مع إبقاء الذراعين قريبين من الرأس.','عد ببطء إلى وضع البداية دون تحريك الوركين للخلف والأمام.'],
 'plank':['ارتكز على الساعدين وأصابع القدمين، واجعل المرفقين أسفل الكتفين.','حافظ على استقامة الرأس والجذع والحوض، وشد البطن والأليتين مع تنفس طبيعي.','اثبت للمدة المحددة، وأنهِ المجموعة إذا تعذر الحفاظ على وضعية مستقيمة.']
};
function exForDay(day){return window.WORKOUT_DATA.filter(x=>x.day===days[day].key)}
function titleCase(s){return s.replace(/\b\w/g,x=>x.toUpperCase())}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function estimate(ex){let n=0;ex.forEach(x=>n+=x.sets*(x.rest+38));return Math.max(20,Math.round(n/60+ex.length*1.2))}
function latestSession(day){return [...state.history].reverse().find(s=>s.day===days[day].title)}
function showHome(){currentPage='home';selectedDay=selectedDay??todayIndex();$('.bottom-nav').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===0));renderHome()}
function renderHome(){const d=days[selectedDay], ex=exForDay(selectedDay), last=latestSession(selectedDay);let cards=days.map((x,i)=>`<button class="day-chip ${i===selectedDay?'selected':''} ${state.history.some(s=>s.day===x.title)?'done':''}" onclick="selectDay(${i})"><span>${dayLabel(x)}</span><strong>${x.rest?'·':String(x.number).padStart(2,'0')}</strong><span>${isArabic()?({'PUSH':'تمارين الدفع','PULL':'تمارين السحب','LEGS':'الساقان','UPPER':'الجزء العلوي','ARMS + DELTS':'ذراعان + كتفان','UPPER + ARMS':'علوي + ذراعان','REST DAY':'استشفاء'}[x.title]||'استشفاء'):x.title.split(' ')[0]}</span></button>`).join('');
app.innerHTML=`<div class="container"><section class="hero"><div class="eyebrow">${new Intl.DateTimeFormat(isArabic()?'ar':'en',{weekday:'long',month:'long',day:'numeric'}).format(new Date()).toUpperCase()}</div><h1>Your week,<br>one rep at a time.</h1><p>Five sessions. One focused leg day. Room to grow.</p></section><div class="week">${cards}</div>${d.rest?restCard(d):`<section class="workout-card"><div class="workout-head"><div><div class="eyebrow">${isArabic()?'اليوم '+d.number+' · '+dayLabel(d):'DAY '+d.number+' · '+d.label.toUpperCase()}</div><h2>${dayTitle(d)}</h2></div><span class="badge">${last?'LAST TRAINED':'TODAY'}</span></div><div class="stats"><div><b>${ex.length}</b> exercises</div><div><b>${estimate(ex)} min</b> estimated</div><div><b>${ex.reduce((a,x)=>a+x.sets,0)}</b> total sets</div></div><div class="exercise-list">${ex.map((x,i)=>`<div class="exercise-row"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${esc(x.name)}<small>${x.sets} × ${esc(x.reps)} · ${targetLabel(x)}</small></span></div>`).join('')}</div><button class="primary full" onclick="warmup()">Start workout <span aria-hidden="true">→</span></button></section>`}<div class="section-title"><h2>Keep the streak easy</h2><span class="eyebrow">WEEK ${Math.floor(state.history.length/5)+1}</span></div><div class="grid2"><div class="small-card"><b>Next deload</b><span>${Math.max(0,6-Math.floor(state.history.length/30))} weeks of training</span></div><div class="small-card"><b>Recent sessions</b><span>${state.history.length} logged workout${state.history.length===1?'':'s'}</span></div></div></div>`}
function restCard(d){return `<section class="workout-card"><div class="eyebrow">RECOVERY DAY</div><h2>${dayTitle(d)}</h2><p class="muted">Let your body adapt. Keep movement light and comfortable.</p><div class="cue">Suggestion: take an easy 20–30 minute walk at a conversational pace.</div><h3>Gentle stretch checklist</h3><div class="rest-check">${['Hip flexor stretch · 30 s each side','Hamstring stretch · 30 s each side','Chest opener · 30 s','Child’s pose · 30 s, only if comfortable'].map((x,i)=>`<label><input type="checkbox" id="stretch${i}"> ${isArabic()?['إطالة مثنيات الورك · ٣٠ ث لكل جانب','إطالة أوتار الركبة · ٣٠ ث لكل جانب','فتح الصدر · ٣٠ ث','وضعية الطفل · ٣٠ ث، عند الشعور بالراحة'][i]:x}</label><br>`).join('')}</div><button class="secondary full" onclick="showHistory()">View progress</button></section>`}
function targetLabel(e){return muscleNames(e.target)|| (isArabic()?'الجسم كامل':'Full body')}
function selectDay(i){selectedDay=i;renderHome()}
function warmup(){const d=days[selectedDay];if(d.rest)return;const ex=exForDay(selectedDay);workout={day:selectedDay,exercises:ex,idx:0,done:ex.map(()=>[]),values:ex.map(x=>previousSets(x)),notes:'',backCheckin:'',start:Date.now(),elapsed:0};drawWarmup()}
function drawWarmup(){overlay.innerHTML=`<div class="drawer-backdrop" onclick="if(event.target===this)closeOverlay()"><section class="drawer modal-wrap"><div class="eyebrow">BEFORE YOU BEGIN</div><h2>Quick warm-up</h2><p class="muted">A little preparation helps you move well through the first working set.</p><label class="checkline"><input type="checkbox"> 5 minutes of easy cardio</label><label class="checkline"><input type="checkbox"> 1–2 ramp-up sets before the first lift</label><div class="modal-actions"><button class="primary full" onclick="beginWorkout()">Let’s train</button><button class="ghost full" onclick="closeOverlay()">Not now</button></div></section></div>`}
async function beginWorkout(){closeOverlay();currentPage='walk';$('.bottom-nav').classList.add('hidden');try{if('wakeLock'in navigator)wake=await navigator.wakeLock.request('screen')}catch(e){} renderWalk();if(sessionClock)clearInterval(sessionClock);sessionClock=setInterval(updateElapsed,1000)}
function updateElapsed(){const el=$('#elapsedClock');if(el&&workout){let s=Math.floor((Date.now()-workout.start)/1000);el.textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}}
function renderWalk(){if(!workout)return;const i=workout.idx,base=workout.exercises[i],swap=window.WORKOUT_DATA.find(x=>x.name===state.swaps[base.id]),e=swap?{...base,name:swap.name,target:swap.target,secondary:swap.secondary,instructions:swap.instructions,images:swap.images,matchedName:swap.matchedName,matchType:swap.matchType}:base,done=workout.done[i],last=lastValues(base),cur=isArabic()?(AR_EXERCISES[base.id]?.name||e.name):e.name,progression=shouldIncrease(base)&&!base.limitedLoad;const target=swap?`Swap · ${targetLabel(e)}`:targetLabel(e),rirHint=rirGuidance(base);let sets=Array.from({length:e.sets},(_,j)=>{const v=workout.values[i][j],loadInput=e.weightless?'':`<label>KG<input aria-label="Set ${j+1} weight in kilograms" type="number" inputmode="decimal" step="0.5" value="${esc(v.weight)}" oninput="setValue(${j},'weight',this.value)" onchange="setValue(${j},'weight',this.value)"></label>`,rir=`<label class="rir-field">RIR<select aria-label="Set ${j+1} reps in reserve" onchange="setValue(${j},'rir',this.value)"><option value="" ${v.rir==null||v.rir===''?'selected':''}>—</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${String(v.rir)===String(n)?'selected':''}>${n}</option>`).join('')}</select></label>`;return `<div class="set ${done.includes(j)?'done':''} ${e.weightless?'set-time':''}"><button class="set-button" aria-label="${isArabic()?`تحديد المجموعة ${j+1} ${done.includes(j)?'غير مكتملة':'مكتملة'}`:`Mark set ${j+1} ${done.includes(j)?'not done':'done'}`}" onclick="toggleSet(${j})">${done.includes(j)?'✓':'SET '+(j+1)}</button>${loadInput}<label>${e.weightless?'SECONDS':'REPS'}<input aria-label="Set ${j+1} ${e.weightless?'seconds':'reps'}" type="number" inputmode="numeric" value="${esc(v.reps)}" oninput="setValue(${j},'reps',this.value)" onchange="setValue(${j},'reps',this.value)"></label>${rir}</div>`}).join('');
const superset=workout.day===5&&i<4?`<div class="superset-banner">SUPERSET ${Math.floor(i/2)+1} · ${i%2===0?'A1':'A2'} — alternate these two exercises, then rest after both.</div>`:'';app.innerHTML=`<div class="container"><div class="walk-head"><div><div class="eyebrow">${dayTitle(days[workout.day])} · EXERCISE ${i+1} OF ${workout.exercises.length} <span style="margin-left:8px">ELAPSED <b id="elapsedClock">00:00</b></span></div><h1>${esc(cur)}</h1></div><div class="walk-controls"><button class="secondary" aria-label="Open exercise overview" onclick="openOverview()">☷</button><button class="secondary" aria-label="Exit workout" onclick="confirmExit()">×</button></div></div><div class="progress-track"><i style="width:${((i+1)/workout.exercises.length)*100}%"></i></div>${superset}<div class="exercise-meta"><span>${e.sets} ${isArabic()?'مجموعات ×':'sets ×'} ${esc(e.reps)}${e.weightless?'':isArabic()?' تكرار':' reps'}</span><span>${e.rest} ${isArabic()?'ث راحة':'s rest'}</span><span>${esc(target)}</span></div><div class="photos">${e.images.map((src,j)=>`<figure><img src="${esc(src)}" alt="${isArabic()?exerciseName(base):esc(e.matchedName)} ${isArabic()?(j===0?'وضعية البداية':'وضعية النهاية'):(j===0?'starting':'ending')+' position'}" loading="lazy"><figcaption>${isArabic()?(j===0?'البداية':'النهاية'):(j===0?'START':'FINISH')}</figcaption></figure>`).join('')}</div>${e.matchType==='EQUIVALENT'?`<div class="lower-note">Image guide: ${esc(e.matchedName)} (closest dataset match)</div>`:''}<div class="instruction-title">${isArabic()?'خطوات الأداء':'HOW TO'}</div><ol class="instructions">${isArabic()?(AR_STEPS[base.id]||['ابدأ من الوضعية الموضحة في الصورة، مع ضبط الجسم والمعدات.','نفّذ الحركة بتحكم مع مراعاة المدى الحركي المريح.','عُد ببطء إلى وضع البداية قبل التكرار التالي.']).map(s=>`<li>${esc(s)}</li>`).join(''):(e.instructions||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="cue"><b>${isArabic()?'نصيحتك الأساسية':'YOUR KEY CUE'}</b><br>${esc(exerciseCue(base))}</div>${isSensitive(e)?`<div class="lower-note">${isArabic()?'توقف إذا أصبح الانزعاج حاداً بدلاً من كونه إجهاداً عضلياً.':'Stop if the discomfort turns sharp rather than muscular.'}${/romanian deadlift/i.test(e.name)?isArabic()?' حافظ على خفة وزن الرفعة الرومانية.':' Keep the RDL light.':''}</div>`:''}<div class="section-title"><h2>${isArabic()?'مجموعات التمرين':'Working sets'}</h2><span class="eyebrow">${isArabic()?'اضغط على الدائرة عند الانتهاء':'TAP A CIRCLE WHEN DONE'}</span></div><div class="sets">${sets}</div><div class="last-line"><span>${rirHint}</span></div><div class="last-line"><span>${progression?(base.weightless?'Progression: hit 45 seconds on every set — try 5 more seconds.':'Progression: top reps on all sets last time — add 2.5 kg.'):base.limitedLoad?(isArabic()?'حافظ على خفة الوزن والتحكم.':'Keep the RDL light and controlled.'):last?(base.weightless?`Last time: ${last.reps} seconds`:`Last time: ${last.weight||'bodyweight'} kg × ${last.reps}`):isArabic()?'لا توجد مجموعة مسجلة سابقاً':'No previous set logged'}</span><button class="quick ${(base.weightless||base.limitedLoad)?'hidden':''}" onclick="quickAdd()">+2.5 kg</button></div><div class="walker-footer"><button class="secondary" onclick="step(-1)" ${i===0?'disabled':''}>${isArabic()?'السابق ←':'← Back'}</button><button class="primary" onclick="step(1)">${i===workout.exercises.length-1?(isArabic()?'إنهاء التمرين':'Finish workout'):(isArabic()?'التمرين التالي →':'Next exercise →')}</button></div><div class="section-title"><h2>${isArabic()?'أدوات التمرين':'Exercise tools'}</h2></div><div class="grid2"><button class="secondary" onclick="swapExercise()">⇄ ${isArabic()?'تبديل التمرين':'Swap exercise'}</button><a class="secondary" style="text-align:center;text-decoration:none;display:grid;place-items:center" target="_blank" rel="noreferrer" href="https://www.youtube.com/results?search_query=${encodeURIComponent(cur+' exercise form')}">▶ ${isArabic()?'فيديوهات توضيحية':'Form videos'}</a></div></div>${timer?timerMarkup():''}`;
if(timer)tickTimer();updateElapsed()}
function isSensitive(e){return e.backCaution===true||/Day 2 · Pull|Day 3 · Legs/.test(e.day)||(e.target||[]).some(m=>['lats','lower back','middle back','quadriceps','hamstrings','glutes'].includes(m))}
function lastValues(e){for(let si=state.history.length-1;si>=0;si--){let hit=state.history[si].exercises?.find(x=>x.id===e.id);if(hit?.sets?.length){const valid=hit.sets.filter(x=>x.weight||x.reps);if(valid.length)return valid.reduce((a,b)=>+b.weight>+a.weight?b:a,valid[0])}}return null}
function previousSets(e){for(let si=state.history.length-1;si>=0;si--){const hit=state.history[si].exercises?.find(x=>x.id===e.id);if(hit?.sets?.length)return Array.from({length:e.sets},(_,j)=>({weight:hit.sets[j]?.weight||'',reps:hit.sets[j]?.reps||''}))}return Array.from({length:e.sets},()=>({weight:'',reps:''}))}
function shouldIncrease(e){for(let si=state.history.length-1;si>=0;si--){const hit=state.history[si].exercises?.find(x=>x.id===e.id);if(!hit)continue;const top=+rangeTop(e.reps);return hit.sets.length>=e.sets&&hit.sets.slice(0,e.sets).every(s=>s.done&&+s.reps>=top&&(s.rir==null||s.rir>=1))}return false}
function rirGuidance(e){const rows=state.history.slice().reverse().flatMap(s=>s.exercises||[]).find(x=>x.id===e.id)?.sets||[];const last=rows.filter(s=>s.done&&s.rir!==''&&s.rir!=null).at(-1);if(last&&+last.rir<1)return 'Effort: very hard last time. Keep the load or reduce slightly and aim for 1–3 reps in reserve.';if(shouldIncrease(e)&&!e.limitedLoad)return 'Effort: all sets reached the rep target. Add the smallest load jump and keep about 1–3 reps in reserve.';return 'Effort target: finish working sets with about 1–3 good reps still in reserve.'}
function setValue(j,key,val){workout.values[workout.idx][j][key]=val}
function quickAdd(){if(workout.exercises[workout.idx].weightless||workout.exercises[workout.idx].limitedLoad)return;const last=lastValues(workout.exercises[workout.idx]);const current=workout.values[workout.idx].find(v=>v.weight)?.weight;const val=current?+current+2.5:(last?+last.weight+2.5:2.5);workout.values[workout.idx].forEach(v=>v.weight=val);renderWalk()}
function toggleSet(j){const arr=workout.done[workout.idx],at=arr.indexOf(j);if(at>=0){arr.splice(at,1);if(timer){clearInterval(timer.interval);timer=null}}else{arr.push(j);arr.sort();workout.values[workout.idx][j].reps ||= rangeTop(workout.exercises[workout.idx].reps);if(state.settings.autoStart){startTimer(workout.exercises[workout.idx].rest)}}renderWalk()}
function rangeTop(r){const m=String(r).match(/(\d+)\s*(?:-|–|to)\s*(\d+)/);return m?m[2]:(String(r).match(/\d+/)||[''])[0]}
function step(n){if(n>0&&workout.idx===workout.exercises.length-1){finishWorkout();return}workout.idx=Math.max(0,Math.min(workout.exercises.length-1,workout.idx+n));renderWalk()}
function openOverview(){overlay.innerHTML=`<div class="drawer-backdrop" onclick="if(event.target===this)closeOverlay()"><section class="drawer"><button class="ghost" onclick="closeOverlay()">Close</button><h2>Workout overview</h2>${workout.exercises.map((e,i)=>`<button type="button" class="drawer-item overview-item" aria-label="Jump to ${esc(state.swaps[e.id]||e.name)}" onclick="jumpTo(${i})"><span class="number">${i+1}</span>${esc(state.swaps[e.id]||e.name)}<span class="status">${workout.done[i].length}/${e.sets}</span></button>`).join('')}</section></div>`}
function jumpTo(i){workout.idx=i;closeOverlay();renderWalk()}
function swapExercise(){const e=workout.exercises[workout.idx],items=swapCandidates(e);overlay.innerHTML=`<div class="drawer-backdrop" onclick="if(event.target===this)closeOverlay()"><section class="drawer"><button class="ghost" onclick="closeOverlay()">Close</button><h2>Swap exercise</h2><p class="muted">Alternatives use available equipment and target similar muscles. Set available equipment in Settings.</p>${items.map(x=>`<button class="swap-preview" onclick="applySwap('${e.id}','${x.id}')"><img src="${esc(x.images[0])}" alt="" loading="lazy"><span><b>${esc(x.name)}</b><small>${esc((x.target||[]).map(titleCase).join(', '))} · ${esc(equipmentTag(x))}</small></span><strong>Use</strong></button>`).join('')||'<p class="muted">No matching alternatives for selected equipment.</p>'}</section></div>`}

function equipmentTag(e){const text=(e.name+' '+(e.instructions||[]).join(' ')).toLowerCase();return ['dumbbell','barbell','cable','machine','bodyweight'].find(x=>text.includes(x))||'gym equipment'}
function swapCandidates(e){const available=new Set(state.settings.equipment||[]),scored=window.WORKOUT_DATA.filter(x=>x.id!==e.id&&x.target?.some(m=>e.target?.includes(m))).map(x=>{const body=x.instructions.join(' ').toLowerCase()+' '+x.name.toLowerCase();const tags=['dumbbell','barbell','cable','machine','bodyweight'].filter(t=>body.includes(t));const matching=available.size===0||tags.length===0||tags.some(t=>available.has(t));const overlap=x.target.filter(m=>e.target.includes(m)).length;return {x,score:overlap*4+(matching?3:-20)}}).filter(v=>v.score>0).sort((a,b)=>b.score-a.score);return scored.slice(0,3).map(v=>v.x)}
function setEquipment(value,checked){const set=new Set(state.settings.equipment||[]);if(checked)set.add(value);else set.delete(value);state.settings.equipment=[...set];save()}
function applySwap(id,name){state.swaps[id]=window.WORKOUT_DATA.find(x=>x.id===name).name;save();closeOverlay();renderWalk()}
function startTimer(seconds){if(timer?.interval)clearInterval(timer.interval);timer={end:Date.now()+seconds*1000,initial:seconds,interval:null,done:false};tickTimer();timer.interval=setInterval(tickTimer,400)}
function setTimerPreset(seconds){if(timer){timer.initial=seconds;timer.end=Date.now()+seconds*1000;timer.done=false;if(timer.interval)clearInterval(timer.interval);timer.interval=setInterval(tickTimer,400);tickTimer()}else startTimer(seconds);renderWalk()}
function adjustTimer(n){if(timer){timer.end+=n*1000;timer.end=Math.max(Date.now(),timer.end);tickTimer()}}
function skipTimer(){if(timer?.interval)clearInterval(timer.interval);timer=null;renderWalk()}
function timerMarkup(){const s=Math.max(0,Math.ceil((timer.end-Date.now())/1000));return `<div class="sticky-timer ${s===0?'timer-flash':''}" id="timerPanel"><div><div class="eyebrow">${isArabic()?'راحة · '+(s===0?'انتهى الوقت':'الوقت المتبقي'):'REST · '+(s===0?'TIME':'REMAINING')}</div><strong>${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}</strong></div><div class="timer-actions"><button onclick="setTimerPreset(30)">30s</button><button onclick="setTimerPreset(60)">60s</button><button onclick="setTimerPreset(90)">90s</button><button onclick="adjustTimer(-15)">−15 ${isArabic()?'ث':'s'}</button><button onclick="adjustTimer(15)">+15 ${isArabic()?'ث':'s'}</button><button onclick="skipTimer()">${isArabic()?'تخطي':'Skip'}</button></div></div>`}
function tickTimer(){if(!timer||currentPage!=='walk')return;const remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));const el=$('#timerPanel');if(el){const strong=el.querySelector('strong');if(strong)strong.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`}if(remaining===0&&!timer.done){timer.done=true;if(timer.interval){clearInterval(timer.interval);timer.interval=null}if(state.settings.vibrate&&navigator.vibrate)navigator.vibrate([250,120,250]);if(state.settings.sound)beep();document.body.classList.add('timer-flash');setTimeout(()=>document.body.classList.remove('timer-flash'),1600);toast('Rest complete — you’re up');}}
function beep(){try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=880;g.gain.value=.15;o.start();o.stop(ctx.currentTime+.25)}catch(e){}}
function confirmExit(){overlay.innerHTML=`<div class="drawer-backdrop"><section class="drawer modal-wrap"><h2>End this workout?</h2><p class="muted">Your completed sets can still be saved to history.</p><div class="modal-actions"><button class="primary full" onclick="finishWorkout()">Finish and save</button><button class="ghost full" onclick="closeOverlay()">Keep training</button></div></section></div>`}
function showSessionCheckin(){workout.reviewing=true;overlay.innerHTML=`<div class="drawer-backdrop"><section class="drawer modal-wrap"><div class="eyebrow">SESSION CHECK-IN</div><h2>How did today feel?</h2><label class="fields">Back discomfort<select id="backCheckin"><option value="baseline" selected>Usual mild discomfort</option><option value="none">None today</option><option value="mild">Mild / unchanged</option><option value="worse">Worse than usual</option><option value="sharp">Sharp discomfort</option></select></label><label class="fields" style="margin-top:14px">Workout note<textarea id="sessionNote" rows="3" placeholder="Energy, technique, or anything to remember…"></textarea></label><div class="modal-actions"><button class="primary full" onclick="workout.backCheckin=$('#backCheckin').value;workout.notes=$('#sessionNote').value;finishWorkout()">Save session</button><button class="ghost full" onclick="workout.reviewing=false;closeOverlay()">Back to workout</button></div></section></div>`}
function finishWorkout(){if(workout&&!workout.reviewing){showSessionCheckin();return}closeOverlay();if(sessionClock)clearInterval(sessionClock);sessionClock=null;if(timer?.interval)clearInterval(timer.interval);timer=null;workout.elapsed=Math.max(1,Math.round((Date.now()-workout.start)/60000));const minutes=workout.elapsed;const exercises=workout.exercises.map((e,i)=>({id:e.id,name:state.swaps[e.id]||e.name,sets:workout.values[i].map((v,j)=>({...v,done:workout.done[i].includes(j)}))}));const session={date:new Date().toISOString(),day:days[workout.day].title,minutes,exercises,note:workout.notes||'',backCheckin:workout.backCheckin||'none'};state.history.push(session);save();const totalSets=exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).length,0),volume=exercises.reduce((n,e)=>n+e.sets.filter(s=>s.done).reduce((a,s)=>a+(+s.weight||0)*(+s.reps||0),0),0);workout=null;currentPage='finish';$('.bottom-nav').classList.remove('hidden');app.innerHTML=`<div class="container"><section class="workout-card"><div class="eyebrow">SESSION COMPLETE</div><h1>Good work.<br>That’s in the books.</h1><p class="muted">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})} · ${days[selectedDay].title}</p><div class="grid2"><div class="small-card"><b>${totalSets}</b><span>sets completed</span></div><div class="small-card"><b>${Math.round(volume).toLocaleString()} kg</b><span>volume logged</span></div><div class="small-card"><b>${minutes} min</b><span>session duration</span></div><div class="small-card"><b>${prCount(session)}</b><span>new PRs</span></div></div><p class="cue">Next time: if you hit the top of the rep range on every set, add the smallest weight jump.</p><button class="primary full" onclick="showHome()">Back to week</button><button class="secondary full" style="margin-top:8px" onclick="showHistory()">See progress</button></section></div>`}
function prCount(session){return session.exercises.reduce((n,e)=>{const best=Math.max(0,...(e.sets||[]).filter(s=>s.done).map(s=>+s.weight||0));const old=Math.max(0,...state.history.slice(0,-1).flatMap(x=>x.exercises||[]).filter(x=>x.id===e.id).flatMap(x=>x.sets||[]).filter(s=>s.done).map(s=>+s.weight||0));return n+(best>old&&best>0?1:0)},0)}

function scheduleEditor(){const workouts=[['Day 1 · Push','Push'],['Day 2 · Pull','Pull'],['Day 3 · Legs','Legs'],['Day 4 · Upper + Arms','Upper + Arms'],['Day 5 · Arms + Delts','Arms + Delts']];const open=['Sat','Sun','Mon','Tue','Wed','Thu'];return workouts.map(([key,name],i)=>`<label class="checkline schedule-row">${name}<select aria-label="${name} day" onchange="moveWorkout(${i},this.value)">${open.map(day=>`<option value="${day}" ${state.settings.schedule?.[i]===day?'selected':''}>${day}</option>`).join('')}</select></label>`).join('')}
function moveWorkout(i,day){const schedule=state.settings.schedule||['Sat','Sun','Mon','Wed','Thu'];const previous=schedule[i],other=schedule.indexOf(day);if(other>=0)schedule[other]=previous;schedule[i]=day;state.settings.schedule=schedule;save();openSettings()}
function backupReminder(){const t=state.settings.lastExport?Date.parse(state.settings.lastExport):0;if(!t)return 'No backup recorded yet. Export a JSON copy to keep a portable backup.';const days=Math.floor((Date.now()-t)/86400000);return days>=14?`It has been ${days} days since your last backup. Export a fresh copy.`:`Last backup: ${new Date(t).toLocaleDateString()} (${14-days} days until reminder).`}
function viewSession(i){const s=state.history[i];if(!s)return;const exercises=(s.exercises||[]).map(e=>`<section class="session-exercise"><h3>${esc(e.name)}</h3><div class="session-set-grid">${(e.sets||[]).map((x,j)=>`<span>Set ${j+1}: ${x.weight||'—'} kg × ${x.reps||'—'}${x.rir==null||x.rir===''?'':` · RIR ${x.rir}`} ${x.done?'✓':'·'}</span>`).join('')}</div></section>`).join('');app.innerHTML=`<div class="container"><button class="secondary" onclick="showHistory()">← Back to progress</button><div class="eyebrow" style="margin-top:20px">SESSION REVIEW</div><h1>${esc(s.day)}</h1><p class="muted">${new Date(s.date).toLocaleString()} · ${s.minutes||0} min</p><div class="cue">Back check-in: ${esc(s.backCheckin||'not recorded')}${s.note?`<br>Note: ${esc(s.note)}`:''}</div>${exercises}</div>`;window.scrollTo(0,0)}
function showHistory(){currentPage='history';$('.bottom-nav').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===1));const chartExercises=[...new Map(window.WORKOUT_DATA.map(e=>[e.id,e])).values()];const options=chartExercises.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');const volume=muscleVolume();app.innerHTML=`<div class="container"><div class="eyebrow">YOUR TRAINING LOG</div><h1>Progress</h1><section class="card"><div class="workout-head"><h2>Weekly muscle volume</h2><span class="badge">working sets</span></div><div class="volume-grid">${volume.map(([muscle,sets])=>`<div class="volume-row"><span>${titleCase(muscle)}</span><b>${sets}</b><i><em style="width:${Math.min(100,sets*10)}%"></em></i></div>`).join('')}</div><p class="muted">Compound sets count for primary muscles. This is a planning estimate.</p></section><section class="card" style="margin-top:14px"><div class="workout-head"><h2>Top set over time</h2><select id="chartExercise" onchange="drawChart()" style="background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:9px;padding:8px;max-width:52%">${options}</select></div><div class="chart-wrap"><svg class="chart" id="chart" viewBox="0 0 600 180" role="img" aria-label="Top set weight chart"></svg></div><span class="muted" style="font-size:11px">Weight (kg) · best logged set per session</span></section><div class="section-title"><h2>Bodyweight</h2><button class="secondary" onclick="logBodyweight()">+ Log weight</button></div><section class="card"><svg id="bodychart" class="chart" viewBox="0 0 600 130"></svg><div class="muted">Optional trend · kg</div></section><div class="section-title"><h2>Past sessions</h2><button class="secondary" onclick="exportData()">Export JSON</button></div><section class="card">${state.history.length?state.history.slice().reverse().map(s=>`<button type="button" class="session-row session-open" onclick="viewSession(${state.history.length-1-state.history.slice().reverse().indexOf(s)})"><span><b>${esc(s.day)}</b><br><small class="muted">${new Date(s.date).toLocaleDateString()} · ${s.minutes||0} min${s.backCheckin&&s.backCheckin!=='none'?` · back: ${esc(s.backCheckin)}`:''}${s.note?` · ${esc(s.note)}`:''}</small></span><span>${s.exercises.reduce((n,e)=>n+e.sets.filter(x=>x.done).length,0)} sets · Review</span></button>`).join(''):'<p class="muted">Sessions you complete will appear here.</p>'}</section><div class="section-title"><h2>Data</h2><span class="muted">${backupReminder()}</span></div><div class="grid2"><button class="secondary" onclick="importFile.click()">Import JSON</button><button class="secondary" onclick="resetData()">Reset all data</button><input id="importFile" class="hidden" type="file" accept="application/json" onchange="importData(this.files[0])"></div></div>`;drawChart();drawBodyChart()}

function muscleVolume(){const totals=new Map();const unique=[...new Map(window.WORKOUT_DATA.map(e=>[e.id,e])).values()];for(const e of unique){for(const m of e.target||[])totals.set(m,(totals.get(m)||0)+e.sets)}return [...totals.entries()].sort((a,b)=>b[1]-a[1])}
function drawChart(){const id=$('#chartExercise')?.value||window.WORKOUT_DATA[0].id;const points=[];state.history.forEach(s=>s.exercises?.filter(e=>e.id===id).forEach(e=>{const sets=e.sets.filter(x=>x.done&&+x.weight>0);if(sets.length)points.push({date:new Date(s.date),weight:Math.max(...sets.map(x=>+x.weight))})}));const svg=$('#chart');if(!svg)return;const w=600,h=180,p=30;svg.innerHTML='<path d="M30 15V150H580" fill="none" stroke="var(--line)"/>'+[0,1,2,3].map(i=>`<path d="M30 ${25+i*40}H580" stroke="var(--line)" stroke-dasharray="3 5"/>`).join('');if(points.length){let max=Math.max(...points.map(x=>x.weight)),min=Math.min(...points.map(x=>x.weight));if(max===min)min=Math.max(0,min-5);let coords=points.map((x,i)=>[p+(points.length===1?270:i*(w-2*p)/(points.length-1)),145-(x.weight-min)/(max-min)*110]);svg.innerHTML+=`<polyline points="${coords.map(c=>c.join(',')).join(' ')}" fill="none" stroke="var(--accent2)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>`+coords.map((c,i)=>`<circle cx="${c[0]}" cy="${c[1]}" r="5" fill="var(--accent)"/><text x="${c[0]}" y="${c[1]-12}" text-anchor="middle" fill="var(--muted)" font-size="12">${points[i].weight}</text>`).join('')}else svg.innerHTML+='<text x="300" y="90" text-anchor="middle" fill="var(--muted)" font-size="14">Log sets with a weight to see your trend</text>'}
function logBodyweight(){const v=prompt('Bodyweight in kg');if(!v||!Number.isFinite(+v))return;state.bodyweight.push({date:new Date().toISOString(),weight:+v});save();showHistory()}
function drawBodyChart(){const svg=$('#bodychart');if(!svg)return;const p=state.bodyweight;if(!p.length){svg.innerHTML='<text x="300" y="68" text-anchor="middle" fill="var(--muted)" font-size="14">Add a bodyweight entry to start your trend</text>';return}let lo=Math.min(...p.map(x=>x.weight)),hi=Math.max(...p.map(x=>x.weight));if(lo===hi){lo-=1;hi+=1}let c=p.map((x,i)=>[30+(i/(Math.max(1,p.length-1)))*540,100-(x.weight-lo)/(hi-lo)*70]);svg.innerHTML=`<polyline points="${c.map(x=>x.join(',')).join(' ')}" fill="none" stroke="var(--accent2)" stroke-width="4"/>`}
function openSettings(){currentPage='settings';$('.bottom-nav').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('active',i===2));app.innerHTML=`<div class="container"><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><section class="card"><h2>Workout</h2>${settingRow('Sound on rest timer','sound')}${settingRow('Vibrate on rest timer','vibrate')}${settingRow('Auto-start rest timer','autoStart')}<div class="fields"><label>Language<select onchange="setLanguage(this.value)"><option value="en" ${state.settings.language==='en'?'selected':''}>English</option><option value="ar" ${state.settings.language==='ar'?'selected':''}>العربية</option></select></label><label>Theme<select onchange="setTheme(this.value)"><option value="dark">Dark</option><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="system">System</option></select></label></div></section><section class="card" style="margin-top:14px"><h2>Training schedule</h2><p class="muted">Choose an open day for each workout. Friday stays closed.</p>${scheduleEditor()}</section><section class="card" style="margin-top:14px"><h2>Available equipment</h2><p class="muted">Exercise swaps will prioritize what you can use.</p>${['dumbbell','barbell','cable','machine','bodyweight'].map(x=>`<label class="checkline">${titleCase(x)}<input class="toggle" type="checkbox" ${(state.settings.equipment||[]).includes(x)?'checked':''} onchange="setEquipment('${x}',this.checked)"></label>`).join('')}</section><section class="card backup-card" style="margin-top:14px"><h2>Backup reminder</h2><p class="muted">${backupReminder()}</p><button class="secondary full" onclick="exportData()">Export backup now</button><p class="muted">Your workouts stay on this device.</p><div class="grid2"><button class="secondary" onclick="exportData()">Export JSON</button><button class="secondary" onclick="$('#importFileSettings').click()">Import JSON</button><input id="importFileSettings" class="hidden" type="file" accept="application/json" onchange="importData(this.files[0])"></div><button class="ghost full" style="margin-top:12px" onclick="resetData()">Reset all data</button></section><section class="card" style="margin-top:14px"><h2>Deload check-in</h2><p class="muted">Every six weeks, consider a lighter week with less volume and comfortable effort. You have logged ${state.history.length} sessions.</p></section></div>`;applyTheme()}
function settingRow(label,key){return `<label class="checkline">${label}<input class="toggle" type="checkbox" ${state.settings[key]?'checked':''} onchange="state.settings.${key}=this.checked;save()"></label>`}
function setTheme(v){state.settings.theme=v;save();applyTheme()}function applyTheme(){let t=state.settings.theme;if(t==='system')t=matchMedia('(prefers-color-scheme: light)').matches?'light':'dark';document.documentElement.dataset.theme=t}
function toggleTheme(){state.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save();applyTheme();if(currentPage==='home')renderHome()}
const AR_UI={'Today':'اليوم','Progress':'التقدم','Settings':'الإعدادات','Your week,':'أسبوعك،','one rep at a time.':'تكراراً بعد تكرار.','Five sessions. One focused leg day. Room to grow.':'خمس حصص تدريبية، بينها يوم ساقين ويوم تخصص للذراعين والكتفين.','Keep the streak easy':'استمر بوتيرة مريحة','Next deload':'أسبوع التخفيف القادم','Recent sessions':'الحصص الأخيرة','Start workout':'ابدأ التمرين','exercises':'تمارين','estimated':'المدة المقدرة','total sets':'مجموعات إجمالاً','LAST TRAINED':'آخر تمرين','TODAY':'اليوم','RECOVERY DAY':'يوم استشفاء','REST DAY':'يوم راحة','Let your body adapt. Keep movement light and comfortable.':'امنح عضلاتك وقتاً للتعافي، واكتفِ بحركة خفيفة ومريحة.','Suggestion: take an easy 20–30 minute walk at a conversational pace.':'اقتراح: امشِ ٢٠–٣٠ دقيقة بوتيرة مريحة.','Gentle stretch checklist':'قائمة إطالات لطيفة','View progress':'عرض التقدم','Quick warm-up':'إحماء سريع','A little preparation helps you move well through the first working set.':'استعد جيداً قبل أول مجموعة عمل.','5 minutes of easy cardio':'٥ دقائق من تمارين الكارديو الخفيفة','1–2 ramp-up sets before the first lift':'مجموعة أو مجموعتان تمهيديتان قبل أول تمرين','Let’s train':'هيا نبدأ','Not now':'ليس الآن','Working sets':'مجموعات العمل','Exercise tools':'أدوات التمرين','TAP A CIRCLE WHEN DONE':'اضغط على الدائرة عند الانتهاء','YOUR KEY CUE':'نصيحتك الأساسية','HOW TO':'طريقة الأداء','No previous set logged':'لا توجد مجموعة مسجلة سابقاً','Back':'السابق','Next exercise':'التمرين التالي','Finish workout':'إنهاء التمرين','Swap exercise':'تبديل التمرين','Form videos':'فيديوهات توضيحية','Workout overview':'ملخص التمرين','Close':'إغلاق','Top set over time':'أفضل وزن مع الوقت','Weekly muscle volume':'الحجم الأسبوعي للعضلات','working sets':'مجموعات العمل','Compound sets count for primary muscles. This is a planning estimate.':'تُحتسب المجموعات المركبة للعضلات الأساسية، وهذا تقدير تخطيطي.','Past sessions':'الحصص السابقة','Bodyweight':'وزن الجسم','Export JSON':'تصدير البيانات','Import JSON':'استيراد البيانات','Reset all data':'حذف كل البيانات','Sound on rest timer':'صوت مؤقت الراحة','Vibrate on rest timer':'اهتزاز مؤقت الراحة','Auto-start rest timer':'بدء مؤقت الراحة تلقائياً','Available equipment':'المعدات المتاحة','Exercise swaps will prioritize what you can use.':'ستُفضّل بدائل التمرين المعدات المتاحة لديك.','dumbbell':'دمبل','barbell':'بار','cable':'كابل','machine':'جهاز','bodyweight':'وزن الجسم','Workout note':'ملاحظة الحصة','Back discomfort':'انزعاج الظهر','SESSION CHECK-IN':'مراجعة الحصة','How did today feel?':'كيف كان شعورك اليوم؟','None':'لا يوجد','Mild / unchanged':'خفيف أو دون تغيير','Worse than usual':'أسوأ من المعتاد','Sharp discomfort':'ألم حاد','Save session':'حفظ الحصة','Back to workout':'العودة للتمرين','RIR':'التكرارات المتبقية','SUPERSET':'مجموعة فائقة','alternate these two exercises, then rest after both.':'بدّل بين هذين التمرينين ثم استرح بعد إكمالهما.','30s':'٣٠ث','60s':'٦٠ث','90s':'٩٠ث','Language':'اللغة','Theme':'المظهر','Dark':'داكن','Light':'فاتح','System':'حسب الجهاز','Data portability':'نسخ البيانات','Deload check-in':'مراجعة أسبوع التخفيف','Preferences':'التفضيلات','Workout':'التمرين','Data imported':'تم استيراد البيانات','Session complete':'اكتملت الحصة','Good work.':'أحسنت.','sets completed':'مجموعات مكتملة','volume logged':'إجمالي الأوزان المسجلة','session duration':'مدة الحصة','new PRs':'أرقام شخصية جديدة','Back to week':'العودة إلى الأسبوع','See progress':'عرض التقدم','Data':'البيانات','Your workouts stay on this device.':'تبقى بياناتك على هذا الجهاز.','Every six weeks, consider a lighter week with less volume and comfortable effort. You have logged':'كل ستة أسابيع، خفف حجم التدريب والجهد. عدد الحصص المسجلة:','Exercise photos & instructions:':'صور التمارين والتعليمات:','free-exercise-db':'قاعدة بيانات التمارين الحرة','Public domain dataset':'مجموعة بيانات ملكية عامة','Program by Chaouki Gali':'إعداد: شوقي قالي','Skip intro':'تخطي المقدمة','BY CHAOUKI GALI':'إعداد: شوقي غالي'};
function updateNavLanguage(language){const nav=document.querySelectorAll('.bottom-nav button'),labels=language==='ar'?['اليوم','التقدم','الإعدادات']:['Today','Progress','Settings'];nav.forEach((b,i)=>{const text=[...b.childNodes].find(x=>x.nodeType===Node.TEXT_NODE);if(text)text.nodeValue=' '+labels[i]})}
function setLanguage(v){if(!['en','ar'].includes(v))return;state.settings.language=v;document.documentElement.lang=v;document.documentElement.dir=v==='ar'?'rtl':'ltr';save();if(currentPage==='home')renderHome();else if(currentPage==='history')showHistory();else if(currentPage==='settings')openSettings();else if(currentPage==='walk')renderWalk();updateNavLanguage(v);if(v==='ar')translatePage();toast(v==='ar'?'تم حفظ اللغة':'Language saved')}
function translatePage(){if(!isArabic())return;for(const root of [app,overlay,document.querySelector('footer'),document.querySelector('#splash')].filter(Boolean)){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){let value=n.nodeValue;for(const [en,ar] of Object.entries(AR_UI).sort((a,b)=>b[0].length-a[0].length))value=value.replaceAll(en,ar);for(const d of days)value=value.replaceAll(d.title,d.ar);for(const [id,x] of Object.entries(AR_EXERCISES)){const e=window.WORKOUT_DATA.find(y=>y.id===id);if(e){value=value.replaceAll(e.name,x.name).replaceAll(e.cue,x.cue)}}n.nodeValue=value}}updateNavLanguage('ar')}
let translationDelay;new MutationObserver(()=>{if(!isArabic())return;clearTimeout(translationDelay);translationDelay=setTimeout(translatePage,80)}).observe(app,{childList:true,subtree:true,characterData:true});
new MutationObserver(()=>{if(!isArabic())return;clearTimeout(translationDelay);translationDelay=setTimeout(translatePage,80)}).observe(overlay,{childList:true,subtree:true,characterData:true});
function exportData(){state.settings.lastExport=new Date().toISOString();save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chax-training-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importData(file){if(!file)return;try{let d=JSON.parse(await file.text());if(!d||typeof d!=='object')throw Error();state={...defaults,...d,settings:{...defaults.settings,...d.settings}};save();toast('Data imported');showHistory()}catch(e){toast('That file is not valid workout data')}}
function resetData(){if(confirm('Reset all workout history, settings, swaps, and bodyweight data?')){try{localStorage.removeItem('iron-data')}catch(e){}state=structuredClone(defaults);document.documentElement.lang='en';document.documentElement.dir='ltr';save();updateNavLanguage('en');toast('All data reset');showHome()}}
function closeOverlay(){overlay.innerHTML=''}function toast(msg){if(isArabic())msg=({'Rest complete — you’re up':'انتهت الراحة، هيا ابدأ','Workout':'التمرين','Data imported':'تم استيراد البيانات','That file is not valid workout data':'ملف البيانات غير صالح','All data reset':'تم حذف جميع البيانات','Could not save data on this device':'تعذر حفظ البيانات على هذا الجهاز'}[msg]||msg);const t=$('#toast');t.textContent=msg;t.className='toast show';setTimeout(()=>t.className='toast',1900)}
let touchX=0;app.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX},{passive:true});app.addEventListener('touchend',e=>{if(currentPage!=='walk')return;const d=e.changedTouches[0].clientX-touchX;if(Math.abs(d)>75)step(d<0?1:-1)},{passive:true});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&timer)tickTimer();if(!document.hidden&&workout&&!wake&&'wakeLock'in navigator)navigator.wakeLock.request('screen').then(x=>wake=x).catch(()=>{})});
document.documentElement.lang=state.settings.language;document.documentElement.dir=state.settings.language==='ar'?'rtl':'ltr';applyTheme();updateNavLanguage(state.settings.language);showHome();if(state.settings.language==='ar')translatePage();window.setTimeout(dismissSplash,950);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=20').catch(()=>{}));

function dismissSplash(){const splash=$('#splash');if(!splash||splash.dataset.dismissed)return;splash.dataset.dismissed='true';splash.classList.add('is-leaving');window.setTimeout(()=>splash.remove(),280)}
